mkdir -p /work/submit && cat > /work/submit/planb64.cpp <<'CPPEOF'
// PlanB64: offline FIB compiler and longest-prefix-match lookup tool.
//
// The tool implements the PlanB reduction of IPv6 longest-prefix matching to
// predecessor search: the routing table is compiled into the minimal
// change-point representation of the step function
//
//     upper64(address) -> (NEXT_HOP, PREFIX_LENGTH)
//
// covering every 64-bit key.  Prefixes are at most 64 bits long, so the upper
// 64 address bits alone decide the answer; the lower 64 bits are still parsed
// and validated.  Lookup is then predecessor search over the change points.
//
// Exit status 0 on success (empty stderr), 2 on any invalid input, invalid
// argument or I/O failure (message on stderr starting with "ERROR:", nothing
// on stdout).
#include <arpa/inet.h>

#include <algorithm>
#include <cerrno>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>

namespace {

// ---------------------------------------------------------------------------
// Limits (documented supported bounds per invocation).
// ---------------------------------------------------------------------------
constexpr size_t   kMaxLine         = 256;        // FIB / trace line cap
constexpr size_t   kMaxImageLine    = 512;        // image line cap
constexpr uint64_t kMaxFibRecords   = 200000;
constexpr uint64_t kMaxTraceRecords = 1000000;
constexpr uint64_t kMaxImageRows    = 400001;
constexpr uint64_t kMaxNextHop      = 4294967295ULL;
constexpr uint64_t kMaxPrefixLen    = 64;
constexpr uint64_t kMaxBatch        = 256;

// ---------------------------------------------------------------------------
// Error reporting.
// ---------------------------------------------------------------------------
struct Error {
    std::string msg;
};

[[noreturn]] void fail(const std::string& m) { throw Error{m}; }

std::string quote(const char* path) {
    std::string s = "'";
    s += path == nullptr ? "(null)" : path;
    s += "'";
    return s;
}

// ---------------------------------------------------------------------------
// Lexical helpers.  All parsing is length based so embedded NUL bytes can
// never truncate a token silently.
// ---------------------------------------------------------------------------
inline bool is_ws(char c) { return c == ' ' || c == '\t' || c == '\r'; }

struct Span {
    const char* p;
    size_t n;
};

// Splits on runs of spaces / tabs / carriage returns.  Returns the token
// count, or max_out + 1 when more tokens exist than the caller allows.
size_t tokenize(const char* p, size_t n, Span* out, size_t max_out) {
    size_t count = 0;
    size_t i = 0;
    while (i < n) {
        while (i < n && is_ws(p[i])) ++i;
        if (i >= n) break;
        size_t begin = i;
        while (i < n && !is_ws(p[i])) ++i;
        if (count == max_out) return max_out + 1;
        out[count].p = p + begin;
        out[count].n = i - begin;
        ++count;
    }
    return count;
}

// FIB and trace records are ASCII text: printable characters plus the three
// documented whitespace characters.  Anything else (control bytes, NUL,
// non-ASCII) makes the record invalid.
void validate_ascii(const std::string& line, const char* what) {
    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (c == '\t' || c == '\r' || c == ' ') continue;
        if (c < 0x20 || c > 0x7e)
            fail(std::string(what) + ": invalid character in input");
    }
}

// Unsigned decimal with arbitrary leading zeros.  Rejects empty strings,
// non-digits (including signs and whitespace) and values above `limit`.
bool parse_dec(const char* p, size_t n, uint64_t limit, uint64_t& out) {
    if (n == 0) return false;
    uint64_t v = 0;
    for (size_t i = 0; i < n; ++i) {
        char c = p[i];
        if (c < '0' || c > '9') return false;
        unsigned d = static_cast<unsigned>(c - '0');
        if (v > (UINT64_MAX - d) / 10) return false;  // overflow
        v = v * 10 + d;
    }
    if (v > limit) return false;
    out = v;
    return true;
}

// Canonical (unpadded) decimal used by the image format.
bool parse_canon_dec(const char* p, size_t n, uint64_t limit, uint64_t& out) {
    if (n == 0) return false;
    if (n > 1 && p[0] == '0') return false;  // padded spelling
    return parse_dec(p, n, limit, out);
}

// Exactly 16 lowercase hexadecimal digits.
bool parse_hex16(const char* p, size_t n, uint64_t& out) {
    if (n != 16) return false;
    uint64_t v = 0;
    for (size_t i = 0; i < 16; ++i) {
        char c = p[i];
        unsigned d;
        if (c >= '0' && c <= '9') d = static_cast<unsigned>(c - '0');
        else if (c >= 'a' && c <= 'f') d = static_cast<unsigned>(c - 'a' + 10);
        else return false;
        v = (v << 4) | d;
    }
    out = v;
    return true;
}

// ---------------------------------------------------------------------------
// Number formatting.
// ---------------------------------------------------------------------------
void append_dec(std::string& s, uint64_t v) {
    char tmp[24];
    int n = 0;
    do {
        tmp[n++] = static_cast<char>('0' + (v % 10));
        v /= 10;
    } while (v != 0);
    while (n > 0) s.push_back(tmp[--n]);
}

void append_int(std::string& s, int64_t v) {
    uint64_t mag;
    if (v < 0) {
        s.push_back('-');
        mag = static_cast<uint64_t>(~static_cast<uint64_t>(v)) + 1ULL;
    } else {
        mag = static_cast<uint64_t>(v);
    }
    append_dec(s, mag);
}

void append_hex16(std::string& s, uint64_t v) {
    static const char digits[] = "0123456789abcdef";
    char tmp[16];
    for (int i = 15; i >= 0; --i) {
        tmp[i] = digits[v & 0xf];
        v >>= 4;
    }
    s.append(tmp, 16);
}

// ---------------------------------------------------------------------------
// Buffered line reader.  Lines are separated by '\n'; a final line without a
// trailing newline is delivered as well, with terminated() == false.  Line
// length is bounded so a hostile input cannot grow memory without limit.
// ---------------------------------------------------------------------------
class LineReader {
public:
    LineReader(const char* path, size_t max_line)
        : path_(path), max_line_(max_line), buf_(1u << 18) {}
    ~LineReader() { close(); }

    LineReader(const LineReader&) = delete;
    LineReader& operator=(const LineReader&) = delete;

    void open() {
        fd_ = ::open(path_, O_RDONLY | O_CLOEXEC);
        if (fd_ < 0)
            fail("cannot open " + quote(path_) + ": " + std::string(std::strerror(errno)));
    }

    bool next(std::string& line) {
        line.clear();
        terminated_ = false;
        for (;;) {
            if (pos_ < len_) {
                const char* base = buf_.data();
                const char* nl =
                    static_cast<const char*>(std::memchr(base + pos_, '\n', len_ - pos_));
                if (nl != nullptr) {
                    size_t cut = static_cast<size_t>(nl - base);
                    append_bounded(line, base + pos_, cut - pos_);
                    pos_ = cut + 1;
                    terminated_ = true;
                    return true;
                }
                append_bounded(line, base + pos_, len_ - pos_);
                pos_ = len_;
            }
            ssize_t r = ::read(fd_, buf_.data(), buf_.size());
            if (r < 0) {
                if (errno == EINTR) continue;
                fail("read error on " + quote(path_) + ": " + std::string(std::strerror(errno)));
            }
            if (r == 0) return !line.empty();
            pos_ = 0;
            len_ = static_cast<size_t>(r);
        }
    }

    bool terminated() const { return terminated_; }

private:
    void append_bounded(std::string& line, const char* p, size_t n) {
        if (line.size() + n > max_line_)
            fail("line exceeds " + std::to_string(max_line_) + " bytes in " + quote(path_));
        if (n != 0) line.append(p, n);
    }

    void close() {
        if (fd_ >= 0) {
            ::close(fd_);
            fd_ = -1;
        }
    }

    const char* path_;
    size_t max_line_;
    std::vector<char> buf_;
    size_t pos_ = 0;
    size_t len_ = 0;
    int fd_ = -1;
    bool terminated_ = false;
};

void write_all_fd(int fd, const char* p, size_t n, const char* what) {
    while (n != 0) {
        ssize_t r = ::write(fd, p, n);
        if (r < 0) {
            if (errno == EINTR) continue;
            fail(std::string(what) + ": " + std::string(std::strerror(errno)));
        }
        p += r;
        n -= static_cast<size_t>(r);
    }
}

// ---------------------------------------------------------------------------
// Address handling.
// ---------------------------------------------------------------------------
// Textual IPv6 address -> upper 64 bits (the routing key).
uint64_t upper64(const char* text) {
    unsigned char bytes[16];
    if (::inet_pton(AF_INET6, text, bytes) != 1) return 0;  // caller validates first
    uint64_t key = 0;
    for (int i = 0; i < 8; ++i) key = (key << 8) | bytes[i];
    return key;
}

// ---------------------------------------------------------------------------
// FIB parsing.
//
//   IPV6_ADDRESS/PREFIX_LENGTH NEXT_HOP
//
// with spaces, tabs and carriage returns as whitespace; blank lines ignored;
// no comments, no extra tokens.  Prefix length 0..64, next hop 0..2^32-1.
// ---------------------------------------------------------------------------
struct Prefix {
    uint64_t key;  // normalized network, upper 64 bits
    uint64_t end;  // first key not covered (0 == 2^64, i.e. a default route)
    uint32_t hop;
    uint32_t len;
};

void parse_fib(const char* path, std::vector<Prefix>& out) {
    LineReader in(path, kMaxLine);
    in.open();
    std::string line;
    Span tok[3];
    char addr[320];
    unsigned char bytes[16];
    while (in.next(line)) {
        validate_ascii(line, "FIB");
        size_t nt = tokenize(line.data(), line.size(), tok, 3);
        if (nt == 0) continue;  // blank line
        if (nt != 2) fail("FIB " + quote(path) + ": record must be 'ADDRESS/LENGTH NEXT_HOP'");

        const Span pf = tok[0];
        size_t slash = 0;
        size_t slashes = 0;
        for (size_t i = 0; i < pf.n; ++i) {
            if (pf.p[i] == '/') {
                if (slashes == 0) slash = i;
                ++slashes;
            }
        }
        if (slashes != 1 || slash == 0 || slash + 1 >= pf.n)
            fail("FIB " + quote(path) + ": malformed prefix '" +
                 std::string(pf.p, pf.n) + "'");
        uint64_t len = 0;
        if (!parse_dec(pf.p + slash + 1, pf.n - slash - 1, kMaxPrefixLen, len))
            fail("FIB " + quote(path) + ": prefix length must be 0..64 ('" +
                 std::string(pf.p + slash + 1, pf.n - slash - 1) + "')");
        size_t alen = slash;
        if (alen + 1 > sizeof(addr)) fail("FIB " + quote(path) + ": address too long");
        if (alen != 0) std::memcpy(addr, pf.p, alen);
        addr[alen] = '\0';
        if (::inet_pton(AF_INET6, addr, bytes) != 1)
            fail("FIB " + quote(path) + ": invalid IPv6 address '" + std::string(addr) + "'");

        const Span nh = tok[1];
        uint64_t hop = 0;
        if (!parse_dec(nh.p, nh.n, kMaxNextHop, hop))
            fail("FIB " + quote(path) + ": next hop must be an unsigned 32-bit decimal ('" +
                 std::string(nh.p, nh.n) + "')");

        if (out.size() >= kMaxFibRecords) fail("FIB " + quote(path) + ": more than 200000 records");

        Prefix p;
        p.len = static_cast<uint32_t>(len);
        p.hop = static_cast<uint32_t>(hop);
        if (len == 0) {
            p.key = 0;                        // host bits are the whole address
            p.end = 0;                        // covers every key: sentinel for 2^64
        } else {
            const uint64_t mask = ~UINT64_C(0) << (64 - len);
            p.key = upper64(addr) & mask;     // clear host bits, lower 64 too
            p.end = p.key + (UINT64_C(1) << (64 - len));
        }
        out.push_back(p);
    }
}

// ---------------------------------------------------------------------------
// Change-point compilation.
//
// Every prefix covers the aligned key range [key, end).  Two such ranges are
// either disjoint or nested, so at any key the covering prefixes form a chain
// and the winner (greatest prefix length) is the deepest one.  The step
// function can only change at range boundaries, hence a sweep over the sorted
// boundary events yields the minimal change-point representation.
// ---------------------------------------------------------------------------
struct Row {
    uint64_t start;
    int32_t hop;
    int32_t len;
};

struct Event {
    uint64_t key;
    uint32_t idx;
    unsigned kind;  // 0 = range end (exclusive), 1 = range start (inclusive)
};

std::vector<Row> compile(std::vector<Prefix>& pf) {
    // Duplicate detection happens on normalized (network, length) pairs.
    std::sort(pf.begin(), pf.end(), [](const Prefix& a, const Prefix& b) {
        if (a.key != b.key) return a.key < b.key;
        return a.len < b.len;
    });
    for (size_t i = 1; i < pf.size(); ++i) {
        if (pf[i].key == pf[i - 1].key && pf[i].len == pf[i - 1].len)
            fail("duplicate normalized prefix (" + std::to_string(pf[i].hop) + " and " +
                 std::to_string(pf[i - 1].hop) + " for the same network and length)");
    }

    std::vector<Event> ev;
    ev.reserve(2 * pf.size());
    for (uint32_t i = 0; i < pf.size(); ++i) {
        ev.push_back(Event{pf[i].key, i, 1});
        if (pf[i].end != 0) ev.push_back(Event{pf[i].end, i, 0});
    }
    std::sort(ev.begin(), ev.end(), [&pf](const Event& a, const Event& b) {
        if (a.key != b.key) return a.key < b.key;
        if (a.kind != b.kind) return a.kind < b.kind;  // ends before starts
        if (a.kind == 1) return pf[a.idx].len < pf[b.idx].len;  // outermost first
        return a.idx < b.idx;
    });

    // Sweep: the stack holds exactly the prefixes covering the current key,
    // ordered outermost..deepest, so the top of the stack is the winner.
    std::vector<Row> rows;
    rows.push_back(Row{0, -1, -1});
    std::vector<uint32_t> stack;
    int32_t cur_hop = -1;
    int32_t cur_len = -1;
    bool first_group = true;
    size_t i = 0;
    while (i < ev.size()) {
        const uint64_t key = ev[i].key;
        while (i < ev.size() && ev[i].key == key) {
            const Event e = ev[i++];
            if (e.kind == 1) {
                stack.push_back(e.idx);
            } else if (!stack.empty() && stack.back() == e.idx) {
                stack.pop_back();
            } else {
                for (size_t k = stack.size(); k-- > 0;) {
                    if (stack[k] == e.idx) {
                        stack.erase(stack.begin() + static_cast<long>(k));
                        break;
                    }
                }
            }
        }
        int32_t hop;
        int32_t len;
        if (stack.empty()) {
            hop = -1;
            len = -1;
        } else {
            const Prefix& w = pf[stack.back()];
            hop = static_cast<int32_t>(w.hop);
            len = static_cast<int32_t>(w.len);
        }
        if (first_group && key == 0) {
            rows[0] = Row{0, hop, len};  // never emit a second row at key 0
        } else if (hop != cur_hop || len != cur_len) {
            rows.push_back(Row{key, hop, len});
        }
        cur_hop = hop;
        cur_len = len;
        first_group = false;
    }
    if (rows.size() > kMaxImageRows) fail("compiled image exceeds 400001 rows");
    return rows;
}

void serialize(const std::vector<Row>& rows, std::string& out) {
    out.clear();
    out.reserve(24 + rows.size() * 31);
    out += "PLANB64 1\n";
    append_dec(out, rows.size());
    out.push_back('\n');
    for (size_t i = 0; i < rows.size(); ++i) {
        append_hex16(out, rows[i].start);
        out.push_back(' ');
        append_int(out, rows[i].hop);
        out.push_back(' ');
        append_int(out, rows[i].len);
        out.push_back('\n');
    }
}

// Publishes the image only once it is complete: a failed build never touches
// an existing destination and never creates a new one.
void publish(const char* dest, const std::string& data) {
    std::string tmpl(dest);
    if (tmpl.size() > 3800) fail("image path too long");
    tmpl += ".tmpXXXXXX";
    std::vector<char> path(tmpl.begin(), tmpl.end());
    path.push_back('\0');
    int fd = ::mkstemp(path.data());
    if (fd < 0)
        fail("cannot create temporary image next to " + quote(dest) + ": " +
             std::string(std::strerror(errno)));
    bool ok = true;
    const char* p = data.data();
    size_t n = data.size();
    while (n != 0) {
        ssize_t r = ::write(fd, p, n);
        if (r < 0) {
            if (errno == EINTR) continue;
            ok = false;
            break;
        }
        p += r;
        n -= static_cast<size_t>(r);
    }
    if (ok && ::fchmod(fd, 0644) != 0) ok = false;
    if (::close(fd) != 0) ok = false;
    if (!ok || ::rename(path.data(), dest) != 0) {
        ::unlink(path.data());
        fail("cannot write image " + quote(dest) + ": " + std::string(std::strerror(errno)));
    }
}

void cmd_build(const char* fib, const char* image) {
    std::vector<Prefix> pf;
    parse_fib(fib, pf);
    const std::vector<Row> rows = compile(pf);
    std::string data;
    serialize(rows, data);
    publish(image, data);
}

// ---------------------------------------------------------------------------
// Image reading.  The image is a standalone interval function; only the
// structural rules of the format are enforced.
// ---------------------------------------------------------------------------
int32_t parse_image_number(const char* p, size_t n, uint64_t limit) {
    if (n == 2 && p[0] == '-' && p[1] == '1') return -1;
    uint64_t v = 0;
    if (!parse_canon_dec(p, n, limit, v))
        fail("image: noncanonical or out-of-range numeric field");
    return static_cast<int32_t>(v);
}

void parse_image_row(const std::string& line, Row& row) {
    const size_t s1 = line.find(' ');
    if (s1 == std::string::npos) fail("image: row must have three fields");
    const size_t s2 = line.find(' ', s1 + 1);
    if (s2 == std::string::npos) fail("image: row must have three fields");
    if (line.find(' ', s2 + 1) != std::string::npos) fail("image: row must have three fields");
    if (s1 == 0 || s2 == s1 + 1 || s2 + 1 >= line.size())
        fail("image: rows use exactly one space between fields");

    uint64_t start = 0;
    if (!parse_hex16(line.data(), s1, start))
        fail("image: start key must be 16 lowercase hexadecimal digits");
    const int32_t hop = parse_image_number(line.data() + s1 + 1, s2 - s1 - 1, kMaxNextHop);
    const int32_t len = parse_image_number(line.data() + s2 + 1, line.size() - s2 - 1, kMaxPrefixLen);
    if ((hop < 0) != (len < 0)) fail("image: no-match fields must be paired");
    if (hop < 0 && (hop != -1 || len != -1)) fail("image: invalid no-match pair");
    row.start = start;
    row.hop = hop;
    row.len = len;
}

void load_image(const char* path, std::vector<Row>& rows) {
    LineReader in(path, kMaxImageLine);
    in.open();
    std::string line;
    if (!in.next(line)) fail("image " + quote(path) + ": missing header");
    if (line != "PLANB64 1") fail("image " + quote(path) + ": bad header or version");
    if (!in.next(line)) fail("image " + quote(path) + ": missing row count");
    uint64_t count = 0;
    if (!parse_canon_dec(line.data(), line.size(), kMaxImageRows, count) || count == 0)
        fail("image " + quote(path) + ": row count must be 1..400001");
    rows.reserve(static_cast<size_t>(count));
    for (uint64_t i = 0; i < count; ++i) {
        if (!in.next(line)) fail("image " + quote(path) + ": fewer rows than announced");
        Row row{0, -1, -1};
        parse_image_row(line, row);
        if (i == 0) {
            if (row.start != 0) fail("image: first key must be 0000000000000000");
        } else {
            const Row& prev = rows.back();
            if (row.start <= prev.start) fail("image: keys must be strictly increasing");
            if (row.hop == prev.hop && row.len == prev.len)
                fail("image: adjacent rows must differ");
        }
        rows.push_back(row);
    }
    std::string extra;
    if (in.next(extra)) fail("image " + quote(path) + ": more rows than announced");
    if (!in.terminated()) fail("image " + quote(path) + ": missing final newline");
}

// ---------------------------------------------------------------------------
// Trace parsing: one IPv6 address per nonblank line.
// ---------------------------------------------------------------------------
void parse_trace(const char* path, std::vector<uint64_t>& keys) {
    LineReader in(path, kMaxLine);
    in.open();
    std::string line;
    Span tok[2];
    char addr[320];
    while (in.next(line)) {
        validate_ascii(line, "TRACE");
        const size_t nt = tokenize(line.data(), line.size(), tok, 2);
        if (nt == 0) continue;  // blank line
        if (nt != 1) fail("TRACE " + quote(path) + ": one address per line expected");
        if (tok[0].n == 0 || tok[0].n + 1 > sizeof(addr))
            fail("TRACE " + quote(path) + ": invalid address");
        if (tok[0].n != 0) std::memcpy(addr, tok[0].p, tok[0].n);
        addr[tok[0].n] = '\0';
        unsigned char bytes[16];
        if (::inet_pton(AF_INET6, addr, bytes) != 1)
            fail("TRACE " + quote(path) + ": invalid IPv6 address '" + std::string(addr) + "'");
        if (keys.size() >= kMaxTraceRecords)
            fail("TRACE " + quote(path) + ": more than 1000000 records");
        keys.push_back(upper64(addr));
    }
}

// ---------------------------------------------------------------------------
// Lookup engines.  Both search the change-point index for the last row whose
// start key does not exceed the query; they only differ in execution shape.
// ---------------------------------------------------------------------------
void append_answer(std::string& out, const Row& r) {
    append_int(out, r.hop);
    out.push_back(' ');
    append_int(out, r.len);
    out.push_back('\n');
}

// scalar: classic binary search per query.
Row scalar_lookup(const Row* rows, size_t n, uint64_t key) {
    size_t lo = 0;
    size_t hi = n;  // invariant: rows[0].start <= key, so an answer always exists
    while (hi - lo > 1) {
        const size_t mid = lo + (hi - lo) / 2;
        if (rows[mid].start <= key)
            lo = mid;
        else
            hi = mid;
    }
    return rows[lo];
}

// batch: chunked execution.  Each chunk walks a branchless (predictate-move)
// search; a one-entry locality hint resolves runs of queries landing in the
// same interval without touching the index at all.
void batch_lookup(const Row* rows, size_t n, const uint64_t* keys, size_t count,
                  size_t& hint, std::string& out) {
    for (size_t j = 0; j < count; ++j) {
        const uint64_t key = keys[j];
        bool hit = key >= rows[hint].start;
        if (hit && hint + 1 < n) hit = key < rows[hint + 1].start;
        if (!hit) {
            const Row* it = rows;
            size_t len = n;
            while (len > 1) {
                const size_t half = len >> 1;
#if defined(__GNUC__)
                __builtin_prefetch(static_cast<const void*>(it + half), 0, 1);
#endif
                it += (it[half].start <= key) ? half : 0;
                len -= half;
            }
            hint = static_cast<size_t>(it - rows);
        }
        append_answer(out, rows[hint]);
    }
}

void cmd_lookup(const char* image, const char* trace, bool batch, uint32_t batch_size) {
    std::vector<Row> rows;
    load_image(image, rows);
    std::vector<uint64_t> keys;
    parse_trace(trace, keys);

    // Everything is validated before the first answer is produced.
    std::string out;
    out.reserve(keys.size() * 14 + 32);
    if (!batch) {
        for (size_t i = 0; i < keys.size(); ++i)
            append_answer(out, scalar_lookup(rows.data(), rows.size(), keys[i]));
    } else {
        const size_t n = keys.size();
        size_t hint = 0;
        for (size_t i = 0; i < n; i += batch_size) {
            const size_t chunk = std::min<size_t>(batch_size, n - i);
            batch_lookup(rows.data(), rows.size(), keys.data() + i, chunk, hint, out);
        }
    }
    write_all_fd(STDOUT_FILENO, out.data(), out.size(), "cannot write answers");
}

uint32_t parse_batch_size(const char* text) {
    const size_t n = std::strlen(text);
    if (n == 0) fail("batch size must be a nonempty string of decimal digits");
    for (size_t i = 0; i < n; ++i)
        if (text[i] < '0' || text[i] > '9')
            fail("batch size must be a string of ASCII digits 0-9");
    uint64_t v = 0;
    if (!parse_dec(text, n, kMaxBatch, v)) fail("batch size must be 1..256");
    if (v == 0) fail("batch size must be 1..256");
    return static_cast<uint32_t>(v);
}

[[noreturn]] void usage() {
    fail("usage: planb64 build FIB IMAGE | planb64 lookup IMAGE TRACE scalar | "
         "planb64 lookup IMAGE TRACE batch BATCH_SIZE");
}

}  // namespace

int main(int argc, char** argv) {
    try {
        if (argc < 2) usage();
        if (std::strcmp(argv[1], "build") == 0) {
            if (argc != 4) usage();
            cmd_build(argv[2], argv[3]);
            return 0;
        }
        if (std::strcmp(argv[1], "lookup") == 0) {
            if (argc == 5 && std::strcmp(argv[4], "scalar") == 0) {
                cmd_lookup(argv[2], argv[3], false, 0);
                return 0;
            }
            if (argc == 6 && std::strcmp(argv[4], "batch") == 0) {
                const uint32_t size = parse_batch_size(argv[5]);
                cmd_lookup(argv[2], argv[3], true, size);
                return 0;
            }
            usage();
        }
        usage();
    } catch (const Error& e) {
        std::fprintf(stderr, "ERROR: %s\n", e.msg.c_str());
        return 2;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "ERROR: %s\n", e.what());
        return 2;
    }
}
